"use strict";

const assert = require("node:assert/strict");
const fs = require("node:fs");
const os = require("node:os");
const path = require("node:path");
const test = require("node:test");
const vm = require("node:vm");
const { scanProject, normalizeUuid, scriptUuidFromType } = require("../lib/core");
const { ResultStore } = require("../lib/model");

// UUID/class IDs below include examples from Creator 3.8's engine and its real
// source serialization, rather than only IDs generated by the implementation.
const IDS = {
    prefab: "11111111-1111-4111-8111-111111111111",
    second: "22222222-2222-4222-8222-222222222222",
    third: "33333333-3333-4333-8333-333333333333",
    texture: "f93c0560-a802-4204-8f66-5655fdef8a08",
    compressedTexture: "f9PAVgqAJCBI9mVlX974oI",
    script: "d292a04a-c822-4e74-874b-5a25f4819fc8",
    scriptType: "d292aBKyCJOdIdLWiX0gZ/I",
    missing: "aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa",
    missingScript: "fc991dd7-0033-4b80-9d41-c8a86a702e59",
    missingScriptType: "fcmR3XADNLgJ1ByKhqcC5Z",
    internal: "bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb",
};

function fixture(t) {
    const projectPath = fs.mkdtempSync(path.join(os.tmpdir(), "cocos-resource-inspector-test-"));
    t.after(() => fs.rmSync(projectPath, { recursive: true, force: true }));
    fs.mkdirSync(path.join(projectPath, "assets"), { recursive: true });
    function write(relative, data) {
        const destination = path.join(projectPath, "assets", relative);
        fs.mkdirSync(path.dirname(destination), { recursive: true });
        fs.writeFileSync(
            destination,
            typeof data === "string" || Buffer.isBuffer(data) ? data : JSON.stringify(data)
        );
        return destination;
    }
    function asset(relative, data, uuid, options = {}) {
        const file = write(relative, data);
        write(`${relative}.meta`, {
            ver: "1.0.0",
            importer: options.importer || "json",
            imported: true,
            uuid,
            files: [],
            subMetas: options.subMetas || {},
            userData: {},
        });
        return file;
    }
    return { projectPath, write, asset };
}

function prefab(components = []) {
    return [
        { __type__: "cc.Prefab", _name: "Demo", data: { __id__: 1 } },
        {
            __type__: "cc.Node",
            _name: "Root",
            _parent: null,
            _children: [{ __id__: 2 }],
            _components: [],
            _id: "root-node-id",
        },
        {
            __type__: "cc.Node",
            _name: "Button",
            _parent: { __id__: 1 },
            _children: [],
            _components: components.map((_, index) => ({ __id__: index + 3 })),
            _id: "button-node-id",
        },
        ...components.map((component) => ({ node: { __id__: 2 }, ...component })),
    ];
}

function createTexture(f) {
    f.asset("textures/button.png", Buffer.from([137, 80, 78, 71]), IDS.texture, {
        importer: "image",
        subMetas: {
            "6c48a": {
                uuid: `${IDS.texture}@6c48a`,
                importer: "texture",
                name: "texture",
                subMetas: {},
            },
            f9941: {
                uuid: `${IDS.texture}@f9941`,
                importer: "sprite-frame",
                name: "spriteFrame",
                subMetas: {},
            },
        },
    });
}

test("normalizes both Creator compressed UUID formats and preserves subasset identity", () => {
    assert.equal(normalizeUuid("fcmR3XADNLgJ1ByKhqcC5Z"), IDS.missingScript);
    assert.equal(normalizeUuid(`${IDS.compressedTexture}@f9941`), `${IDS.texture}@f9941`);
    assert.equal(normalizeUuid(IDS.scriptType), IDS.script);
    assert.equal(normalizeUuid(IDS.script.toUpperCase()), IDS.script);
    assert.equal(scriptUuidFromType(IDS.scriptType), IDS.script);
    for (const builtin of [
        "cc.Node",
        "cc.UITransform",
        "sp.Skeleton",
        "dragonBones.ArmatureDisplay",
        "CCPropertyOverrideInfo",
        "MyNamedData",
    ]) {
        assert.ok(
            !scriptUuidFromType(builtin),
            `${builtin} must not be treated as a missing script UUID`
        );
    }
});

test("indexes a valid sprite subasset and locates its exact component and property", async (t) => {
    const f = fixture(t);
    createTexture(f);
    f.asset(
        "ui/Demo.prefab",
        prefab([
            { __type__: "cc.Sprite", _spriteFrame: { __uuid__: `${IDS.compressedTexture}@f9941` } },
        ]),
        IDS.prefab
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.equal(result.version, 1);
    assert.equal(result.projectPath, f.projectPath);
    assert.ok(result.assets.some((asset) => asset.uuid === `${IDS.texture}@f9941`));
    const reference = result.references.find(
        (item) => item.targetUuid === `${IDS.texture}@f9941` && item.sourceUuid === IDS.prefab
    );
    assert.ok(reference, "compressed serialized reference must resolve to the exact subasset");
    assert.equal(reference.sourceUrl, "db://assets/ui/Demo.prefab");
    assert.match(reference.nodePath, /Root\/Button$/);
    assert.equal(reference.nodeId, "button-node-id");
    assert.equal(reference.component, "cc.Sprite");
    assert.match(reference.property, /_spriteFrame/);
    assert.equal(reference.objectIndex, 3);
    assert.ok(!result.issues.some((issue) => issue.targetUuid === `${IDS.texture}@f9941`));
});

test("reports missing assets and missing subassets even when their parent image exists", async (t) => {
    const f = fixture(t);
    createTexture(f);
    f.asset(
        "ui/Demo.prefab",
        prefab([
            {
                __type__: "cc.Sprite",
                _spriteFrame: { __uuid__: `${IDS.texture}@does-not-exist` },
                another: { __uuid__: IDS.missing },
            },
        ]),
        IDS.prefab
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    for (const targetUuid of [`${IDS.texture}@does-not-exist`, IDS.missing]) {
        const issue = result.issues.find(
            (item) =>
                item.targetUuid === targetUuid &&
                ["MISSING_ASSET", "UNRESOLVED_ASSET"].includes(item.code)
        );
        assert.ok(issue, `must flag exact missing target ${targetUuid}`);
        assert.match(issue.nodePath, /Root\/Button$/);
    }
    assert.ok(
        !result.issues.some((issue) => issue.targetUuid === IDS.texture),
        "existing parent image is not missing"
    );
});

test("uses Editor internal and nested subasset records without treating their virtual files as missing", async (t) => {
    const f = fixture(t);
    const internalSub = `${IDS.internal}@f9941`;
    f.asset(
        "ui/Demo.prefab",
        prefab([{ __type__: "cc.Sprite", _spriteFrame: { __uuid__: internalSub } }]),
        IDS.prefab
    );
    const result = await scanProject({
        projectPath: f.projectPath,
        assetInfos: [
            {
                uuid: IDS.internal,
                url: "db://internal/default.png",
                file: path.join(f.projectPath, "not-a-project-file.png"),
                type: "cc.ImageAsset",
                importer: "image",
                readonly: true,
                subAssets: {
                    f9941: {
                        uuid: internalSub,
                        url: "db://internal/default.png/spriteFrame",
                        type: "cc.SpriteFrame",
                        importer: "sprite-frame",
                    },
                },
            },
        ],
    });
    assert.ok(result.assets.some((asset) => asset.uuid === internalSub));
    assert.ok(result.references.some((reference) => reference.targetUuid === internalSub));
    assert.ok(
        !result.issues.some(
            (issue) =>
                issue.targetUuid === internalSub || issue.sourceUrl === "db://internal/default.png"
        ),
        "known internal resources are neither missing nor missing-source errors"
    );
});

test("current disk metadata invalidates a stale Editor subasset instead of hiding a broken reference", async (t) => {
    const f = fixture(t);
    f.asset("textures/button.png", Buffer.from([137, 80, 78, 71]), IDS.texture, {
        importer: "image",
        subMetas: {},
    });
    f.asset(
        "ui/Demo.prefab",
        prefab([{ __type__: "cc.Sprite", _spriteFrame: { __uuid__: `${IDS.texture}@f9941` } }]),
        IDS.prefab
    );
    const result = await scanProject({
        projectPath: f.projectPath,
        assetInfos: [
            {
                uuid: IDS.texture,
                url: "db://assets/textures/button.png",
                importer: "image",
                subAssets: {
                    f9941: {
                        uuid: `${IDS.texture}@f9941`,
                        url: "db://assets/textures/button.png/spriteFrame",
                        importer: "sprite-frame",
                    },
                },
            },
        ],
    });
    assert.ok(!result.assets.some((asset) => asset.uuid === `${IDS.texture}@f9941`));
    assert.ok(
        result.issues.some(
            (issue) => issue.code === "MISSING_ASSET" && issue.targetUuid === `${IDS.texture}@f9941`
        )
    );
});

test("recognizes script class IDs and avoids reporting engine types as missing scripts", async (t) => {
    const f = fixture(t);
    f.asset("scripts/Game.ts", "export class Game {}", IDS.script, { importer: "typescript" });
    f.asset(
        "ui/Demo.prefab",
        prefab([
            { __type__: IDS.scriptType },
            { __type__: IDS.missingScriptType },
            { __type__: "cc.UITransform" },
            { __type__: "sp.Skeleton" },
            { __type__: "dragonBones.ArmatureDisplay" },
            { __type__: "MyNamedData" },
        ]),
        IDS.prefab
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.ok(
        result.references.some(
            (reference) =>
                reference.sourceUuid === IDS.prefab && reference.targetUuid === IDS.script
        )
    );
    const issues = result.issues.filter((issue) => issue.code === "MISSING_SCRIPT");
    assert.equal(issues.length, 1);
    assert.equal(issues[0].targetUuid, IDS.missingScript);
    assert.match(issues[0].nodePath, /Root\/Button$/);
});

test("continues past malformed asset and meta JSON and still resolves healthy files", async (t) => {
    const f = fixture(t);
    createTexture(f);
    f.asset("broken.prefab", "[{ bad json", IDS.second);
    f.write("broken-image.png", Buffer.from([1, 2, 3]));
    f.write("broken-image.png.meta", "{ broken meta");
    f.asset(
        "valid.prefab",
        prefab([{ __type__: "cc.Sprite", _spriteFrame: { __uuid__: `${IDS.texture}@f9941` } }]),
        IDS.prefab
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.ok(
        result.issues.some(
            (issue) => issue.code === "INVALID_JSON" && issue.sourceUrl.endsWith("/broken.prefab")
        )
    );
    assert.ok(result.issues.some((issue) => issue.code === "INVALID_META"));
    assert.ok(
        result.references.some(
            (reference) =>
                reference.sourceUuid === IDS.prefab &&
                reference.targetUuid === `${IDS.texture}@f9941`
        )
    );
});

test("reports out-of-range local references and maps PrefabInfo dependencies to their owner node", async (t) => {
    const f = fixture(t);
    const data = prefab([{ __type__: "cc.Sprite", missingNode: { __id__: 999 } }]);
    data[2]._prefab = { __id__: 4 };
    data.push({
        __type__: "cc.PrefabInfo",
        root: { __id__: 1 },
        asset: { __uuid__: IDS.missing },
        fileId: "button-file-id",
    });
    f.asset("ui/Demo.prefab", data, IDS.prefab);
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.ok(
        result.issues.some(
            (issue) =>
                issue.code === "INVALID_LOCAL_REFERENCE" && /missingNode/.test(issue.property)
        )
    );
    const reference = result.references.find(
        (item) => item.targetUuid === IDS.missing && item.objectIndex === 4
    );
    assert.ok(reference);
    assert.match(reference.nodePath, /Root\/Button$/);
});

test("dependency and deletion-impact traversal terminates on cycles and distinguishes direct from transitive dependents", async (t) => {
    const f = fixture(t);
    f.asset(
        "A.prefab",
        prefab([{ __type__: "cc.Component", asset: { __uuid__: IDS.second } }]),
        IDS.prefab
    );
    f.asset(
        "B.prefab",
        prefab([{ __type__: "cc.Component", asset: { __uuid__: IDS.prefab } }]),
        IDS.second
    );
    f.asset(
        "C.prefab",
        prefab([{ __type__: "cc.Component", asset: { __uuid__: IDS.second } }]),
        IDS.third
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    const impact = new ResultStore(result).getImpact({ uuid: IDS.prefab });
    assert.deepEqual(
        impact.direct.map((asset) => asset.uuid),
        [IDS.second]
    );
    assert.deepEqual(
        impact.transitive.map((asset) => asset.uuid),
        [IDS.third]
    );
    assert.equal(impact.truncated, false);
    assert.ok(![...impact.direct, ...impact.transitive].some((asset) => asset.uuid === IDS.prefab));
});

test("deleting a physical image includes references to its sprite subasset", async (t) => {
    const f = fixture(t);
    createTexture(f);
    f.asset(
        "Demo.prefab",
        prefab([{ __type__: "cc.Sprite", _spriteFrame: { __uuid__: `${IDS.texture}@f9941` } }]),
        IDS.prefab
    );
    const result = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    const store = new ResultStore(result);
    assert.equal(store.queryReferences({ uuid: IDS.texture }).total, 1);
    assert.deepEqual(
        store.getImpact({ uuid: IDS.texture }).direct.map((asset) => asset.uuid),
        [IDS.prefab]
    );
});

test("a fresh scan reflects changed and deleted references without stale cached results", async (t) => {
    const f = fixture(t);
    createTexture(f);
    f.asset(
        "Demo.prefab",
        prefab([{ __type__: "cc.Sprite", _spriteFrame: { __uuid__: `${IDS.texture}@f9941` } }]),
        IDS.prefab
    );
    const before = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.ok(
        before.references.some(
            (reference) =>
                reference.sourceUuid === IDS.prefab &&
                reference.targetUuid === `${IDS.texture}@f9941`
        )
    );
    f.write("Demo.prefab", prefab([{ __type__: "cc.Sprite", _spriteFrame: null }]));
    const after = await scanProject({ projectPath: f.projectPath, assetInfos: [] });
    assert.ok(
        !after.references.some(
            (reference) =>
                reference.sourceUuid === IDS.prefab &&
                reference.targetUuid === `${IDS.texture}@f9941`
        )
    );
});

test("reference limits also bound dependency storage and explicitly mark incomplete results", async (t) => {
    const f = fixture(t);
    f.asset(
        "Demo.prefab",
        prefab([
            {
                __type__: "cc.Component",
                first: { __uuid__: IDS.second },
                second: { __uuid__: IDS.third },
                third: { __uuid__: IDS.missing },
            },
        ]),
        IDS.prefab
    );
    const result = await scanProject({
        projectPath: f.projectPath,
        assetInfos: [],
        limits: { maxReferences: 1 },
    });
    assert.equal(result.references.length, 1);
    const source = result.assets.find((asset) => asset.uuid === IDS.prefab);
    assert.equal(
        source.dependencies.length,
        1,
        "unretained references must not continue growing an unbounded dependency set"
    );
    assert.equal(result.summary.partial, true);
    assert.ok(result.limitations.length > 0);
});

test("cancellation is explicit and does not produce a complete-looking report", async (t) => {
    const f = fixture(t);
    f.asset("Demo.prefab", prefab(), IDS.prefab);
    try {
        const result = await scanProject({ projectPath: f.projectPath, isCancelled: () => true });
        assert.equal(result.summary.cancelled, true);
        assert.equal(result.summary.partial, true);
    } catch (error) {
        assert.match(`${error.code || ""} ${error.message}`, /cancel|取消|abort/i);
    }
});

function sceneMethods(root, currentUuid = IDS.prefab) {
    const source = fs.readFileSync(path.join(__dirname, "../scene.js"), "utf8");
    const exports = {};
    vm.runInNewContext(
        source,
        {
            exports,
            require(name) {
                assert.equal(name, "cc");
                return { director: { getScene: () => root } };
            },
            Editor: {
                Message: {
                    request: async (...args) => {
                        assert.equal(args[0], "scene");
                        assert.equal(args[1], "query-current-scene");
                        return currentUuid;
                    },
                },
            },
        },
        { filename: "scene.js" }
    );
    return exports.methods;
}

test("node location requires the source asset to be currently open", async () => {
    const root = {
        name: "Root",
        uuid: "root",
        children: [{ name: "Button", uuid: "button", children: [] }],
    };
    const result = await sceneMethods(root, IDS.second).findNode({
        sourceUuid: IDS.prefab,
        nodePath: "Root/Button",
    });
    assert.ok(result.message);
    assert.ok(!result.uuid);
});

test("node location supports Prefab isolation wrappers and rejects ambiguous duplicate paths", async () => {
    const first = { name: "Button", uuid: "button-1", children: [] };
    const prefabRoot = { name: "Root", uuid: "prefab-root", children: [first] };
    const root = { name: "EditorScene", uuid: "editor-scene", children: [prefabRoot] };
    const methods = sceneMethods(root);
    const unique = await methods.findNode({ sourceUuid: IDS.prefab, nodePath: "Root/Button" });
    assert.equal(unique.uuid, "button-1");
    prefabRoot.children.push({ name: "Button", uuid: "button-2", children: [] });
    const ambiguous = await methods.findNode({ sourceUuid: IDS.prefab, nodePath: "Root/Button" });
    assert.ok(ambiguous.message);
    assert.ok(!ambiguous.uuid);
});

test("serialized node IDs take precedence over duplicate names and never fall back to a replacement node", async () => {
    const root = {
        name: "Root",
        uuid: "root",
        children: [
            { name: "Button", uuid: "button-original", children: [] },
            { name: "Button", uuid: "button-replacement", children: [] },
        ],
    };
    const methods = sceneMethods(root);
    const found = await methods.findNode({
        sourceUuid: IDS.prefab,
        nodePath: "Root/Button",
        nodeId: "button-original",
    });
    assert.equal(found.uuid, "button-original");
    root.children.shift();
    const stale = await methods.findNode({
        sourceUuid: IDS.prefab,
        nodePath: "Root/Button",
        nodeId: "button-original",
    });
    assert.ok(stale.message);
    assert.ok(!stale.uuid);
});
